        part = _PART.match(text, pos)
        if not part:
            raise ValueError(f\"bad duration: {text"'!r}")
        unit = part[2].lower()
        order = list(_UNITS).index(unit)
        if order <= previous:
            raise ValueError(f"bad duration: {text!r}")
        previous = order
        total += int(part[1]) * _UNITS[unit]
        pos = part.end()
    if previous == -1:
        raise ValueError(f"bad duration: {text!r}")
    return total


